65	/// A track with a fresh id, copying `from`'s name and its hidden / muted /
66	/// locked / solo / matte state (the matte only provisionally: `nest_clips`
67	/// keeps it by the carry rule alone), and its volume and pan when
68	/// `keeps_mix` (spec §11 AU-102).
69	///
70	/// The state is copied and not cleared: a selection taken off a muted track
71	/// must go on sounding the way it did, and the mute now lives on the nest's
72	/// own track where the user can find it. Solo copies for the same reason —
73	/// what played before nesting plays after — even though a solo is judged
74	/// per container, so inside the nest it is now judged among the nest's own
75	/// tracks.
76	///
77	/// Volume and pan are copied from every source track but the nest clip's
78	/// destination, whose copy gets `keeps_mix` false and so unity and centre:
79	/// the destination track still applies over the nest clip, and a fader
80	/// applied twice is not a fader applied once (where muting twice is muting
81	/// once, so mute copies from it too).
82	///
83	/// A compressor or limiter is never copied (spec §11 AU-150): a nest's own
84	/// tracks have none, and the destination's still apply over the nest clip.
85	fn nested_track(project: &mut Project, from: &Track, keeps_mix: bool) -> Track {
86	    Track {
87	        id: project.allocate_id(),
88	        name: from.name.clone(),
89	        hidden: from.hidden,
90	        muted: from.muted,
91	        locked: from.locked,
92	        solo: from.solo,
93	        matte: from.matte,
94	        volume: if keeps_mix { from.volume } else { 1.0 },
95	        pan: if keeps_mix { from.pan } else { 0.0 },
96	        compressor: None,
97	        limiter: None,
98	    }
99	}
