101	impl Project {
102	    /// Collapses `clips` into one nest clip (spec §6).
103	    ///
104	    /// The clips keep their relative times — the earliest starts at 0 inside
105	    /// the nest — their relative track order, their props and their actions;
106	    /// the nest clip covers exactly the span they covered, on the front-most
107	    /// track any of them was on.
108	    ///
109	    /// An empty selection, and a selection of one clip that is already a
110	    /// nest (grouping a group alone changes nothing a user can see), are
111	    /// identities. A nest clip that would break the overlap rule against
112	    /// whatever was NOT selected is refused, in the rule's own sentence. `Err` on an unknown clip id or a selection
113	    /// that would put the project past the track cap.
114	    pub fn nest_clips(&self, clips: &[u32], name: Option<&str>) -> Result<Outcome, String> {
115	        // A linked partner goes in with its clip (spec §11 AU-91).
116	        let selected: Vec<Clip> = self
117	            .selected_clips(&self.with_links(clips)?)?
118	            .into_iter()
119	            .cloned()
120	            .collect::<Vec<_>>();
121	        if selected.is_empty() {
122	            return Ok(Outcome::Identity);
123	        }
124	        if selected.len() == 1 && matches!(selected[0].source, Source::Nest { .. }) {
125	            return Ok(Outcome::Identity);
126	        }
127	        // An adjustment clip grades the top level only (spec §11 GR-6).
128	        if let Some(found) = selected.iter().find(|c| is_adjustment(c)) {
129	            return Ok(Outcome::Refused(adjustment_cannot_nest(found.id)));
130	        }
131	
132	        let earliest = selected.iter().map(|c| c.start).min().unwrap_or(0);
133	        let latest = selected.iter().map(clip_end).max().unwrap_or(0);
134	        if latest <= earliest {
135	            return Ok(Outcome::Identity);
136	        }
137	
138	        // The source tracks, back-most first, so the nest's own stack keeps
139	        // the order the timeline had. `track_index` is the stack position;
140	        // a clip on a track that is not in `tracks` cannot exist (`validate`
141	        // refuses it) and is skipped rather than defended against twice.
142	        let mut sources: Vec<(usize, u32)> = Vec::new();
143	        for clip in &selected {
144	            if let Some(index) = self.track_index(clip.track) {
145	                if !sources.iter().any(|(_, id)| *id == clip.track) {
146	                    sources.push((index, clip.track));
147	                }
148	            }
149	        }
150	        sources.sort_unstable();
151	        // The front-most source track that is not a matte track is where
152	        // the nest clip goes (MT-5): a matte pair nested together must land
153	        // where its picture was drawn, not on the matte track, where the
154	        // whole nest would become a matte. The front-most when all are. The
155	        // nest's own tracks count toward `MAX_TRACKS` like any other
156	        // (`format::check_caps`), so a selection that would overrun the cap
157	        // is caught by `finish` rather than counted twice here.
158	        let drawn = sources
159	            .iter()
160	            .rev()
161	            .find(|(_, id)| self.track(*id).is_some_and(|t| t.matte.is_none()));
162	        let Some((_, front_track)) = drawn.or(sources.last()).copied() else {
163	            return Ok(Outcome::Identity);
164	        };
165	
166	        let mut next = self.clone();
167	        let nest_id = next.allocate_id();
168	        let mut tracks: Vec<Track> = Vec::with_capacity(sources.len());
169	        let mut mapping: Vec<(u32, u32)> = Vec::with_capacity(sources.len());
170	        for (_, id) in &sources {
171	            let Some(source) = self.track(*id) else {
172	                continue;
173	            };
174	            let track = nested_track(&mut next, source, *id != front_track);
175	            mapping.push((*id, track.id));
176	            tracks.push(track);
177	        }
178	        // The carry rule (MT-5), one pass over the mapping: a nested track
179	        // stays a matte only when the nested track directly behind it is the
180	        // copy of its source's target. A matte nested without its target
181	        // draws inside the nest as an ordinary track (owner, O9).
182	        for index in 0..tracks.len() {
183	            let from = mapping.get(index).map(|(from, _)| *from);
184	            let behind = index
185	                .checked_sub(1)
186	                .and_then(|i| mapping.get(i))
187	                .map(|(from, _)| *from);
188	            let carried = from.and_then(|from| matte_target(&self.tracks, from));
189	            if carried.is_none() || carried != behind {
190	                if let Some(track) = tracks.get_mut(index) {
191	                    track.matte = crate::model::TrackMatte::None;
192	                }
193	            }
194	        }
195	
196	        // The clips move WHOLE — ids, actions, transitions and all — so
197	        // nothing about them has to be re-minted or re-checked. Only their
198	        // container changes.
199	        let mut inside: Vec<Clip> = Vec::with_capacity(selected.len());
200	        for clip in &selected {
201	            let Some((_, track)) = mapping.iter().find(|(from, _)| *from == clip.track) else {
202	                continue;
203	            };
204	            let mut moved = clip.clone();
205	            moved.track = *track;
206	            moved.start = clip.start.saturating_sub(earliest);
207	            inside.push(moved);
208	        }
209	        // Any sound inside means the nest clip needs a volume of its own to
210	        // scale it by; a nest of text and shapes gets no audio group, so the
211	        // inspector shows no Audio tab for something that cannot make a
212	        // sound.
213	        let audible = inside.iter().any(|c| c.audio.is_some());
214	
215	        next.clips
216	            .retain(|c| !selected.iter().any(|s| s.id == c.id));
217	        next.nests.push(Nest {
218	            id: nest_id,
219	            name: match name.map(str::trim).filter(|n| !n.is_empty()) {
220	                Some(given) => given.to_string(),
221	                None => format!("Nest {}", next.nests.len().saturating_add(1)),
222	            },
223	            width: next.canvas.width,
224	            height: next.canvas.height,
225	            tracks,
226	            clips: inside,
227	        });
228	
229	        let clip_id = next.allocate_id();
230	        // A transition INTO the selection belonged to a clip that is now
231	        // inside the group, so the nest clip gets the default cross
232	        // dissolve over whatever overlap it inherits — the same rule
233	        // every other op uses for a clip that gains one.
234	        next.clips.push(Clip {
235	            video: Some(VideoProps::default()),
236	            audio: audible.then(AudioProps::default),
237	            ..Clip::placed(
238	                clip_id,
239	                front_track,
240	                earliest,
241	                latest.saturating_sub(earliest),
242	                Source::Nest { project: nest_id },
243	            )
244	        });
245	
246	        if let Err(why) = next.check_overlap_rule(&[], front_track, &[]) {
247	            return Ok(Outcome::Refused(why));
248	        }
249	        self.finish_placement(next, &[front_track])
250	    }
