252	    /// Puts a nest clip's contents back on the timeline and removes the clip
253	    /// (spec §6) — the inverse of [`Project::nest_clips`].
254	    ///
255	    /// Each clip returns at `clip.start + its own start`, with fresh ids, on
256	    /// the track counted back from the nest clip's own: the nest's
257	    /// front-most NON-matte track (the front-most when all are, MT-5) lands
258	    /// where the nest clip was, the one behind it a track further back, a
259	    /// carried matte track in front of it a track further forward, and
260	    /// tracks missing behind are added. A clip the overlap rule refuses —
261	    /// or a matte clip with no track in front — goes on a new track in
262	    /// front, ordinary: `unnest` makes no track a matte.
263	    ///
264	    /// The nest itself is dropped when nothing else shows it; a second clip
265	    /// showing it keeps it, which is why the returned clips are copies.
266	    /// `Err` when `clip` is not a nest clip.
267	    pub fn unnest_clip(&self, clip: u32) -> Result<Outcome, String> {
268	        let target = self.require_clip(clip)?.clone();
269	        let Source::Nest { project } = target.source else {
270	            return Err(format!("clip {clip} is not a nest clip"));
271	        };
272	        // `validate` refuses a clip pointing at a nest that is not there, so
273	        // this is a corrupt project rather than a caller's mistake — an
274	        // error either way, naming both ids.
275	        let nest = self
276	            .nest(project)
277	            .ok_or_else(|| format!("clip {clip} shows unknown nest {project}"))?
278	            .clone();
279	
280	        let base = self.require_track_index(target.track)? as i64;
281	        // The nest's front-most non-matte track, the one the nest clip's own
282	        // track stands for (MT-5); the front-most when all are mattes.
283	        let front = nest
284	            .tracks
285	            .iter()
286	            .rposition(|t| t.matte.is_none())
287	            .unwrap_or(nest.tracks.len().saturating_sub(1)) as i64;
288	        let depth = |track: u32| -> i64 {
289	            // 0 for `front`, counting backwards; negative for a carried
290	            // matte track in front of it.
291	            match nest.tracks.iter().position(|t| t.id == track) {
292	                Some(index) => front - index as i64,
293	                None => 0,
294	            }
295	        };
296	        // Bounded by the track cap the project was read under, so the
297	        // deficit loop below can ask for at most `MAX_TRACKS` tracks and
298	        // `finish` refuses the result if that is too many.
299	        let deepest = front;
300	
301	        let mut next = self.clone();
302	        next.clips.retain(|c| c.id != clip);
303	
304	        // Tracks missing behind the destination, exactly as `paste` adds
305	        // them: inserting at index 0 shifts every existing track up, so the
306	        // destination index moves with them.
307	        let base = next.add_tracks_behind(deepest, base);
308	
309	        // Back-most first, then time: the order clips are placed in is the
310	        // order the overlap rule sees them, so it has to be deterministic or
311	        // one nest could open two ways.
312	        let mut ordered: Vec<&Clip> = nest.clips.iter().collect();
313	        ordered.sort_by_key(|c| (std::cmp::Reverse(depth(c.track)), c.start, c.id));
314	
315	        let mut landing = Landing::new(base);
316	        let first = next.clips.len();
317	        let mut fresh: HashMap<u32, u32> = HashMap::new();
318	        for source in ordered {
319	            let mut moved = source.clone();
320	            next.remint(&mut moved);
321	            fresh.insert(source.id, moved.id);
322	            // Translate first; the shared normalization then handles a
323	            // hand-written or legacy off-grid nest on the parent grid.
324	            moved.start = target.start.saturating_add(source.start);
325	            next.resnap_clip_times(&mut moved);
326	            landing.land(&mut next, moved, depth(source.track));
327	        }
328	        // The returning clips re-pair through their fresh ids (AU-96).
329	        if let Some(landed) = next.clips.get_mut(first..) {
330	            relink_copies(landed, &fresh);
331	        }
332	
333	        if !next.nest_is_shown(project) {
334	            next.nests.retain(|n| n.id != project);
335	        }
336	        self.finish_placement(next, landing.touched())
337	    }
338	}
339	//! Editing INSIDE a nest — the envelope's `scope` key (spec §6, §4.4).
340	//!
341	//! Every `clip`, `track` and `action` argument in the op table resolves
342	//! through [`Project::clip`] and its siblings, which search `self.clips`
343	//! and `self.tracks` and nothing else. That is what made a nest a closed
344	//! box: no op could name what was in one, and the way in was the round trip
345	//! — `unnest`, edit, `nest` — which is the identity on clip content but
346	//! throws the nest clip's own group-level properties away.
347	//!
348	//! **The fix is not to teach sixty-four ops about nests.** It is to give
349	//! the ENVELOPE a scope, and to hand the op a project in which the nest's
350	//! own tracks and clips are the top level. Then `Project::clip` keeps its
351	//! one meaning, `apply_op` keeps its flat dispatch, every refusal and every
352	//! clamp every op documents holds unchanged, and undo stays one stack of
353	//! parent handles because what comes back out is still a whole
354	//! [`Project`].
355	//!
356	//! ### The view
357	//!
358	//! [`Project::scoped_view`] is the nest as a project:
359	//!
360	//! | Key | Value | Why |
361	//! |---|---|---|
362	//! | `canvas.width` / `height` | the NEST's frozen pair | a nest is composited at the size it was made at ([`Nest`]), so that is the canvas its contents are placed against — `add_background`'s plate and `add_zoom_action`'s solve both read it |
363	//! | `canvas.fps`, `background`, `fit_new_clips`, `timecode_frames`, `output`, `blending` | the PARENT's | a [`Nest`] has none of them. The rate matters: every time argument snaps to the document's frame grid, and there is only one grid; the output, because a nest composes in its document's dynamic range (spec §11 HD-2); the blending, because a nest is flattened into its document's recipe and blends as it does (HD-16 (a)) |
364	//! | `tracks` / `clips` | the nest's | the whole point |
365	//! | `media` | the parent's | a nest references the parent's `media[]` in the parent's one id space (spec §5.2); a view with none would fail `validate` on the first clip that shows a file |
366	//! | `nests` | the parent's, with the scoped one EMPTIED | see below — this is neither "the parent's" nor "the parent's minus the scope" |
367	//! | `markers` | none | a nest has no markers, and the timeline's are project time |
368	//! | `next_id` | the parent's | one id space, so an id minted inside is minted for the whole document |
369	//!
370	//! **The scoped nest's row stays and its CONTENTS go**, and both halves
371	//! are load-bearing. Neither of the two obvious answers works:
372	//!
373	//! - *Leave it whole* and `validate` refuses the view. Its uniqueness
374	//!   sweep inserts every `self.clips` id into one `HashSet` and then every
375	//!   `nest.clips` id into the SAME set, because a nest holds its clips in
376	//!   the parent's one id space. A view whose top level is nest 4's clips
377	//!   AND whose `nests[]` still holds nest 4 inserts every one of them
378	//!   twice, so the answer is `duplicate id N on a clip in nest 4` — and
379	//!   [`Project::finish`] validates every op result, so the FIRST op applied
380	//!   in any scope would be an `Err`. `check_caps` double-counts for the
381	//!   same reason.
382	//! - *Take the row out altogether* and `validate` refuses the view again,
383	//!   in the case the phase exists for. `check_clips` resolves every
384	//!   `Source::Nest` against `nests[]`, in EVERY container, so scoping into
385	//!   a nest that another nest shows — a nest inside a nest, which is what
386	//!   "go one level in" usually means — leaves that other nest's clip
387	//!   naming a nest the view has not got: `clip 172 in nest 170 refers to
388	//!   unknown nest 180`. Measured, not reasoned: it is what the depth test
389	//!   below reported before this paragraph existed.
390	//!
391	//! So the row is kept with `tracks` and `clips` emptied. The id resolves,
392	//! nothing is counted twice, and the emptiness is unreachable: a nest
393	//! cannot show itself at any remove (`check_nesting` refuses a cycle), so
394	//! no clip at the view's top level can name the scope, and the flattening
395	//! walk only ever descends from there. It is also what keeps `nest`'s
396	//! default name — `Nest <nests.len() + 1>` — counting the same list inside
397	//! a scope as outside it.
398	//!
399	//! The other nests are the parent's own, whole. They have to be: a nest
400	//! clip INSIDE the scope shows one of them, and `check_clips` would refuse
401	//! it otherwise.
402	//!
403	//! ### The merge
404	//!
405	//! [`Project::merge_scope`] writes the nest's `tracks` and `clips`,
406	//! `next_id`, `media` and `nests` back into a clone of the parent, and
407	//! leaves the canvas, the markers and the timeline's own clips exactly as
408	//! they were.
409	//!
410	//! **What the merge does NOT write is the half that keeps the markers
411	//! safe**, and the mutation run said so: giving the view the parent's
412	//! markers is an EQUIVALENT mutant today, because the three marker ops are
413	//! refused and the merge discards whatever the view did to them. The empty
414	//! `markers` on the view is defence — an `insert_time` inside a nest should
415	//! not spend its time shifting a list that is about to be thrown away — and
416	//! the load-bearing rule is that a scoped edit never writes markers back. A
417	//! future change that added them to this list would be the real bug, and it
418	//! is killed by `a_scoped_edit_does_not_move_the_timelines_markers`.
419	//!
420	//! `media` is on that list because of one op. `paste` appends a row for
421	//! every payload path the project does not already carry
422	//! (`edit_paste.rs`), so a paste inside a scope that dropped the view's
423	//! media would leave the pasted clips naming a media the parent has not
424	//! got, and the merged parent would fail `check_clips` with `clip N refers
425	//! to unknown media M`. It is a straight replace rather than a union
426	//! because on this path the list can only GROW: `add_media`, `relink_media`
427	//! and `remove_media` are refused inside a scope, so nothing else reorders,
428	//! rewrites or removes a row.
429	//!
430	//! `nests` is the subtle one, and the rule is **union first, orphans
431	//! after**. `unnest` ends by dropping the nest it opened when
432	//! `nest_is_shown` says nothing else shows it, and `nest_is_shown` asks
433	//! `every_clip()` — the project's own clips plus every nest's. In a view
434	//! the project's own clips are the SCOPED nest's, and the parent's timeline
435	//! clips are not there at all, so un-nesting an inner nest clip that a
436	//! timeline clip also shows judges that nest unused and drops it; the merge
437	//! would then leave the parent's clip dangling. Two clips sharing one nest
438	//! is a real state — `duplicate` clones the source rather than the group —
439	//! so this is not a corner. The merge therefore takes the UNION, dropping
440	//! nothing the view dropped, and only then asks the MERGED parent's own
441	//! `nest_is_shown` about each one. Keeping an orphan is harmless (an
442	//! orphaned nest is a legal project — `check_nesting` walks them
443	//! deliberately); dropping a shown one is a corrupt document.
444	//!
445	//! ### The result, which has a wider third arm
446	//!
447	//! A scoped op answers spec §5.5's three ways like any other, and it exits
448	//! through the same [`Project::finish`] — but the `Err` arm can fire where
449	//! no unscoped op can reach, because **two invariants are invisible from
450	//! inside a scope**:
451	//!
452	//! - **The caps.** `format::check_caps` sums the timeline's clips and
453	//!   tracks with every nest's, deliberately, so 64 nests of 64 tracks
454	//!   cannot slip past a cap that exists to bound exactly that. A view holds
455	//!   the nest's clips at top level and the parent's timeline clips nowhere,
456	//!   so its totals are strictly LOWER than the document's and an op refused
457	//!   at the parent's cap would be accepted inside a scope.
458	//! - **The depth.** `check_nesting` starts every walk at level 1, so a view
459	//!   cannot see how deep the nest it is already sits. A `nest` inside a
460	//!   scope at depth 8 builds a level-9 stack the view validates happily.
461	//!
462	//! Neither can be answered by the view, and neither should be answered
463	//! twice, so both are answered ONCE, at the end, by validating the MERGED
464	//! parent. The contract, stated so a caller can rely on it:
465	//!
466	//! - `Ok(Outcome::Applied(project))` — the view changed and the merged
467	//!   parent holds every invariant.
468	//! - `Ok(Outcome::Identity)` — the op is valid and the view changed
469	//!   nothing, or the merge came out equal to the project it started from.
470	//!   No undo step, exactly as at the top level.
471	//! - `Ok(Outcome::Refused(why))` — a rule inside the view declined the op,
472	//!   in its own words, which come back out of the scope unchanged: a rule
473	//!   about clips says the same thing whichever project they were counted
474	//!   in. No undo step either.
475	//! - `Err(message)` — `scope` names no nest; the op has no meaning inside
476	//!   one; the op's own arguments are invalid IN THE VIEW (an id that is not
477	//!   in this nest is `no clip with id N`, which is the honest answer);
478	//!   **or** the merged parent fails an invariant the view could not see —
479	//!   `too many clips`, `too many tracks`, `nests are more than 8 deep at
480	//!   nest N`. That last group is the one worth reading twice: *an op may
481	//!   succeed against the view and the scoped apply still return `Err`.*
