490	/// Reads the envelope's `scope` out of the value `edit::parse` removed.
491	///
492	/// `None` for absent and for an explicit `null` — the envelope's standing
493	/// rule that the two mean the same thing — and an `Err` naming the value
494	/// for anything that is not a nest id, which is any u32. A negative number,
495	/// a fraction, a numeric STRING and a bool all land there: a scope decides
496	/// which document an edit lands in, so guessing at one is the last thing to
497	/// do.
498	pub(crate) fn read(value: Option<&Value>) -> Result<Option<u32>, String> {
499	    match value {
500	        None | Some(Value::Null) => Ok(None),
501	        Some(found) => found
502	            .as_u64()
503	            .and_then(|id| u32::try_from(id).ok())
504	            .map(Some)
505	            .ok_or_else(|| format!("scope must be a nest id, not {}", describe(found))),
506	    }
507	}
