509	/// The ops with no meaning inside a nest, by name, or `None` for the
510	/// fifty-six that work in there unchanged.
511	///
512	/// Exhaustive rather than a short list with a `_` arm, and that is the
513	/// point of writing it out: an op added by a later phase does not compile
514	/// until somebody has decided which side of this line it falls on. The
515	/// compiler is the reviewer.
516	fn refused_inside(op: &Op) -> Option<&'static str> {
517	    match op {
518	        // A nest has no `markers[]` (spec §5.2). The timeline's markers are
519	        // PROJECT time and chapter points on the exported file; a marker
520	        // measured from a nest's own zero would be neither.
521	        Op::AddMarker { .. } => Some("add_marker"),
522	        Op::SetMarker { .. } => Some("set_marker"),
523	        Op::RemoveMarker { .. } => Some("remove_marker"),
524	
525	        // Half of a canvas is not a nest's to have — the rate, the
526	        // background and the two switches are the document's — and the half
527	        // that is, its size, is FROZEN at the size the parent had when the
528	        // nest was made, so that a later `set_canvas` cannot silently
529	        // re-lay-out content nobody touched ([`Nest`]). Honouring that here
530	        // would be `set_canvas` reaching through a scope to do the one
531	        // thing the freeze exists to stop.
532	        Op::SetCanvas { .. } => Some("set_canvas"),
533	
534	        // A nest references the parent's `media[]` in the parent's one id
535	        // space (spec §5.2). So a media edit inside a scope is a media edit
536	        // on the document wearing a scope — the same act, spelled twice —
537	        // and `remove_media` is worse than redundant: it would strip the
538	        // clips that show the file from the view's containers and leave
539	        // every TIMELINE clip that shows it dangling, since those are not
540	        // in the view to be found.
541	        Op::AddMedia { .. } => Some("add_media"),
542	        Op::RelinkMedia { .. } => Some("relink_media"),
543	        Op::RemoveMedia { .. } => Some("remove_media"),
544	        Op::SetMediaColor { .. } => Some("set_media_color"),
545	        Op::SetMediaSpeech { .. } => Some("set_media_speech"),
546	        Op::SetMediaCursor { .. } => Some("set_media_cursor"),
547	
548	        // An adjustment clip grades what is behind it at the top level only
549	        // (spec §11 GR-6): `check_clips` refuses one inside a nest, so the
550	        // op is refused here before a view is built.
551	        Op::AddAdjustmentClip { .. } => Some("add_adjustment_clip"),
552	
553	        // A range kept as a whole project is the DOCUMENT's timeline, edited
554	        // only on a derived document (spec §11 CJ-50); a nest has none.
555	        Op::KeepRange { .. } => Some("keep_range"),
