                + "leave the nest (⌘↑) to jump to it"
            : "Move the playhead to this marker"
        let remove = OptionButtonControl(
            title: "Delete",
            action: { binding.apply("Remove Marker", [.removeMarker(marker: id)]) },
            enabled: { true }, onEdit: {})
        return inspectorRow(nil, [chapter, jump, remove])
    }
