    /// hand-written file is refused at level 9 rather than walked.
    fn nest_height(
        &self,
        id: u32,
        level: u32,
        chain: &mut Vec<u32>,
        known: &mut HashMap<u32, u32>,
    ) -> Result<u32, String> {
