                    video.motion = None;
                }
            }
        }
    };
    private func beginClipDrag(anchor: UInt32, at point: CGPoint, flags: NSEvent.ModifierFlags) {
        guard let clip = snapshot.clip(anchor),
              let index = snapshot.trackIndex(of: clip.track),
